(* [comment removed for export] *)
Definition RK_kfp (d h : Z) : Z := if d =? 8 then RK_kern h else 0.
Definition RB_kfp (d h w : Z) : Z := if d =? 8 then RB_kern h w else 0.

Lemma RK_kfp_8 : forall h, RK_kfp 8 h = RK_kern h.
Proof.
ltac2:(KReplay.run1 (kr_t_LeptRoomK ()) [] "h01hp;1p;2g00\bj11Tg005Dj20Tg00OhR0f0#1,00W0o"). Qed.
Lemma RB_kfp_8 : forall h w, RB_kfp 8 h w = RB_kern h w.
Proof.
ltac2:(KReplay.run1 (kr_t_LeptRoomK ()) [] "h01hh11wp;2g00J2j21Tg005Dj20Tg00OhR0f1f0'1,00X10W0o"). Qed.

Lemma kfp_cost_bound : forall d h w, 1 <= h <= 20000 -> 1 <= w <= 20000 -> (d = 8 -> w * h <= 2 ^ 26) ->
